import numpy as np
rng = np.random.default_rng(0)
I = np.eye(2); X = np.array([[0, 1], [1, 0]]); Y = np.array([[0, -1j], [1j, 0]]); Z = np.diag([1., -1])
def apply(kr, rho): return sum(K @ rho @ K.conj().T for K in kr)
def td(a, b): return 0.5 * np.abs(np.linalg.eigvalsh(a - b)).sum()
def rand_state():
    r = rng.normal(size=3); r *= rng.uniform() ** (1 / 3) / np.linalg.norm(r)    # random point of the Bloch ball
    return 0.5 * (I + r[0] * X + r[1] * Y + r[2] * Z)
g, p, q, s = 0.3, 0.2, 0.4, 0.36
psi = np.array([np.sqrt(1 - s), np.sqrt(s)])
chans = {
    "amplitude damping": ([np.diag([1, np.sqrt(1 - g)]), np.array([[0, np.sqrt(g)], [0, 0]])], np.sqrt(1 - g)),
    "dephasing":         ([np.sqrt(1 - p) * I, np.sqrt(p) * Z], 1.0),
    "depolarising":      ([np.sqrt(1 - 3 * q / 4) * I] + [np.sqrt(q / 4) * P for P in (X, Y, Z)], 1 - q),
    "reset":             ([np.outer(psi, [1, 0]), np.outer(psi, [0, 1])], 0.0),
}
for name, (kr, eta) in chans.items():
    best = max(td(apply(kr, a), apply(kr, b)) / td(a, b) for a, b in ((rand_state(), rand_state()) for _ in range(20000)))
    print(f"{name:18s} formula eta = {eta:.3f}   largest ratio found over 20000 random pairs = {best:.3f}")

import numpy as np
rng = np.random.default_rng(1)
I = np.eye(2); X = np.array([[0, 1], [1, 0]]); Z = np.diag([1., -1])
n = 3; D = 2 ** n

def op(o, i):
    m = np.array([[1.]])
    for k in range(n): m = np.kron(m, o if k == i else I)
    return m

def hamiltonian(h):
    r = np.random.default_rng(1); H = np.zeros((D, D))
    for i in range(n):
        for j in range(i + 1, n): H += r.uniform(-0.5, 0.5) * op(X, i) @ op(X, j)
    return H + h * sum(op(Z, i) for i in range(n))

def step(rho, s, U):
    """Reset qubit 1 to sqrt(1-s)|0> + sqrt(s)|1>, then evolve: rho -> U (psi psi^T (x) Tr_1 rho) U^dag."""
    r4 = rho.reshape(2, D // 2, 2, D // 2)
    psi = np.array([np.sqrt(1 - s), np.sqrt(s)])
    return U @ np.kron(np.outer(psi, psi), r4[0, :, 0, :] + r4[1, :, 1, :]) @ U.conj().T

def trace_distance(a, b):
    return 0.5 * np.abs(np.linalg.eigvalsh(a - b)).sum()

def superoperator(s, U):
    """The channel for a fixed input s as a D^2 x D^2 matrix acting on vec(rho)."""
    S = np.zeros((D * D, D * D), complex)
    for k in range(D * D):
        E = np.zeros(D * D, complex); E[k] = 1
        S[:, k] = step(E.reshape(D, D), s, U).reshape(-1)
    return S

for h in [0.0, 1.0]:
    E, V = np.linalg.eigh(hamiltonian(h)); U = V @ np.diag(np.exp(-10j * E)) @ V.conj().T
    lam = np.sort(np.abs(np.linalg.eigvals(superoperator(0.3, U))))[::-1]
    plus = np.array([1, 1]) / np.sqrt(2); minus = np.array([1, -1]) / np.sqrt(2); z = np.array([1., 0])
    a = np.kron(np.kron(z, plus), z); b = np.kron(np.kron(z, minus), z)
    ra, rb = np.outer(a, a).astype(complex), np.outer(b, b).astype(complex)
    d = []
    for k, s in enumerate(rng.uniform(0, 1, 60)):
        ra, rb = step(ra, s, U), step(rb, s, U)
        if k + 1 in (1, 10, 30, 60): d.append(trace_distance(ra, rb))
    print(f"h = {h}: |eigenvalues| of the s=0.3 channel: {np.round(lam[:5], 4)}; "
          f"D after 1, 10, 30, 60 steps: {np.round(d, 4)}")
